void test__test_range__test_when_patterns(void) {
testsupport__assert__assert_eq_i32(test__test_range__classify_char('a'), 1, KOBEL_STR("classify 'a'"));
testsupport__assert__assert_eq_i32(test__test_range__classify_char('z'), 1, KOBEL_STR("classify 'z'"));
testsupport__assert__assert_eq_i32(test__test_range__classify_char('M'), 1, KOBEL_STR("classify 'M'"));
testsupport__assert__assert_eq_i32(test__test_range__classify_char('0'), 2, KOBEL_STR("classify '0'"));
testsupport__assert__assert_eq_i32(test__test_range__classify_char('9'), 2, KOBEL_STR("classify '9'"));
testsupport__assert__assert_eq_i32(test__test_range__classify_char('!'), 0, KOBEL_STR("classify '!'"));
testsupport__assert__assert_eq_i32(test__test_range__classify_num(0), 1, KOBEL_STR("classify 0"));
testsupport__assert__assert_eq_i32(test__test_range__classify_num(9), 1, KOBEL_STR("classify 9"));
testsupport__assert__assert_eq_i32(test__test_range__classify_num(10), 2, KOBEL_STR("classify 10"));
testsupport__assert__assert_eq_i32(test__test_range__classify_num(20), 2, KOBEL_STR("classify 20"));
testsupport__assert__assert_eq_i32(test__test_range__classify_num(40), 3, KOBEL_STR("classify 40"));
testsupport__assert__assert_eq_i32(test__test_range__classify_num(50), 3, KOBEL_STR("classify 50"));
testsupport__assert__assert_eq_i32(test__test_range__classify_num(30), 3, KOBEL_STR("classify 30"));
testsupport__assert__assert_eq_i32(test__test_range__classify_num(99), 0, KOBEL_STR("classify 99"));
testsupport__assert__assert_eq_i32(test__test_range__classify_desc_half(10), 1, KOBEL_STR("classify_desc_half 10"));
testsupport__assert__assert_eq_i32(test__test_range__classify_desc_half(1), 1, KOBEL_STR("classify_desc_half 1"));
testsupport__assert__assert_eq_i32(test__test_range__classify_desc_half(0), 0, KOBEL_STR("classify_desc_half 0"));
testsupport__assert__assert_eq_i32(test__test_range__classify_desc_half(11), 0, KOBEL_STR("classify_desc_half 11"));
testsupport__assert__assert_eq_i32(test__test_range__test_when_stmt('c'), 1, KOBEL_STR("when stmt 'c'"));
testsupport__assert__assert_eq_i32(test__test_range__test_when_stmt('X'), 2, KOBEL_STR("when stmt 'X'"));
testsupport__assert__assert_eq_i32(test__test_range__test_when_stmt('5'), 3, KOBEL_STR("when stmt '5'"));
testsupport__assert__assert_eq_i32(test__test_range__test_when_stmt('?'), -1, KOBEL_STR("when stmt '?'"));
}

